INSERT INTO `texty` (`text_id`, `text_nazev`, `text_kr`, `text_dl`, `text_datumod`, `text_datumdo`, `text_autor`, `text_sekce`) VALUES
(1, 'Vznik stránek', '', '<center>Tyto stránky vznikly jako gratulace ke <h3>30. narozeninám</h3> <strong>Petra Hališky</strong>.\r\nCelý tým autorů je přesvědčen, že jeho život, který úspěšně dospěl do své druhé čtvrtiny má co nabídnout.\r\nNechť jsou tyto stránky věčným důkazem, že mistr Hališka je správný borec, věrný fanoušek, milující manžel a\r\n<h3>super kamarád</h3>.\r\n\r\n<obr>DSC01884.JPG</obr>\r\n\r\nVerča, Šárka, Lukáš, Martin, Pavel\r\nV Šilheřovicích, dne 21. ledna 2006.\r\n</center>', '2006-01-21', '0000-00-00', 8, 26),
(2, 'Petr a dívky', '', '<center>\r\nDochovaných dokumentů o osobním životě Petra Hališky není mnoho. Velmi cenná je proto fotografie jedné z celé řady zájemkyň o jeho osobu.\r\n<obr>Scan0003.jpg</obr>\r\nVeřejnosti známější je novodobá historie jeho osobního života. Legendární je jeho přitažlivost pro osoby stejného pohlaví, na což však neexistuje relevantní důkaz. Není nutno dodávat, že tento zájem nijak neopětoval, spíše naopak, jak je ostatně zřejmé z následujících fotografií.\r\n<obr>DSC01826.JPG</obr>\r\n<obr>DSC00513.JPG</obr>\r\nOsud byl nakonec k Petrovi zaslouženě spravedlivý a poslal mu do cesty dívku odpovídající jeho nárokům a zároveň ženu praktickou, se smyslem pro péči o zdraví a domácnost svého manžela.\r\nČímž zároveň prozrazujeme, jak onen vztah nakonec šťastně vyvrcholil.\r\n<obr>DSC00491.JPG</obr>\r\n<obr>DSC01799.JPG</obr>\r\n<obr>Scan0007.jpg</obr>\r\n</center>\r\n', '2007-12-01', '0000-00-00', 8, 22),
(3, 'Petr mnoha tváří', '', '<obr>DSC00572.JPG</obr>\r\n<obr>DSC00541.JPG</obr>\r\n<obr>Secan0001.jpg</obr>\r\n<obr>Scan0008.jpg</obr>\r\n<obr>DSC02965.JPG</obr>\r\n<obr>Scan0006.jpg</obr>\r\n<obr>Scan0005.jpg</obr>\r\n<obr>DSC00464.JPG</obr>\r\n', '2007-12-02', '0000-00-00', 8, 25),
(4, 'Petr a práce', '', '<center>\r\nV každém zaměstnání Petr sklízel úspěchy za svou pracovitost a loajalitu. Přes výrobce aut se nakonec vypracoval v předního správce nejmodernějších softwarů a patří k uznávaným odborníkům. Tyto aktivity bohužel nelze doložit žádnou fotodokumentací.\r\nAktivně se však Petr také chopí fyzicky náročné a vyčerpávající práce, což dokazují následující snímky.\r\n<obr>DSC02363.JPG</obr>\r\n<obr>DSC00454.JPG</obr>\r\nNejkvalitnější práci však nakonec Petr odvedl na vlastní svatbě, kde obratně a s citem přebalil téměř živé dítě.\r\n<obr>Scan0009.jpg</obr>\r\n</center>\r\n', '2007-12-03', '0000-00-00', 8, 23),
(5, 'Petr a sport', '', '<center>\r\nNa úplné vylíčení sportovní stránky Petrova života by byl potřeba několik set stránkový román. Projdeme proto pouze pár základních úspěchů.\r\nTím prokazatelně největším je zisk mistrovského titulu jeho milovaného Baníku v roce 2004, což dokumentuje fotografie patřící do zlatého fondu Petrova archivu. Jako správný fanoušek si titul trošku přivlastnil.\r\n<obr>Scan0011.jpg</obr>\r\nVelmi důležitou součástí Petrova života je také aktivní sport, ve kterém dosahuje velmi kvalitních výsledků. Bohužel se ještě nenašel správný sportovní manažer, který by odhalil jeho talent a dal jej v šanc profesionálnímu sportu. Ale co není může být.\r\n<obr>DSC03012.JPG</obr>\r\n<obr>DSC01809.JPG</obr>\r\n<obr>Scan0004.jpg</obr>\r\n<obr>Scan0002.jpg</obr>\r\n<obr>Scan0001.jpg</obr>\r\n<obr>DSC03020.JPG</obr>\r\nTuto kapitolu nelze ukončit jinak, než tolik zbožňovaným Baníkem, takže nabízíme ještě pár pomůcek správného fanouška.\r\n<obr>fcb_banik_rain_1024.jpg</obr>\r\n<obr>Novyobrazek.JPG</obr>\r\n<obr>Novyobrazek2.JPG</obr>\r\n</center>\r\n', '2007-12-04', '0000-00-00', 8, 21),
(6, 'Petr a tvorba', '', '<center>\r\nHlavní životní hodnotou Petra je snaha zanechat tady dalším generacím kus svých vlastních myšlenek.\r\nSvětlo světa tak spatřily desítky velmi osobních básní - většina z nich však skončila dle přání autora v šuplíku či koši. Filozofii Petrova života však nejlépe vyjadřuje jedna kompozice, jejíž část byla ještě v útlém věku autora zveřejněna.\r\nJako jedni z mála tak máte možnost se ponořit do vznešených a hlubokých slov - vrcholu české poezie.\r\n\r\n<strong>Bez názvu</strong>\r\nJano,\r\nsvlékni pyžamo,\r\nlehni na záda,\r\nbude paráda.\r\nRoztáhni stehýnka,\r\nstrčím Ti tam šulínka.\r\n\r\n(vydáno koncem osmdesátých let na ZŠ Studénka)\r\n</center>\r\n', '2007-12-05', '0000-00-00', 8, 24),
(93, '9. amatérské fotbalové utkání září 2009', '', '<center>\r\nKonečně po dlouhé době přálo počasí. Slunečno již od rána, teplota se vyšplhala v čase zápasu na 25°C. S tím souvisela větší spotřeba nealko a piva po zápase.\r\n\r\nI když se to opět neobešlo bez pozdních omluvenek, nastoupili proti sobě téměř totožné týmy jako na jaře. Narychlo pozvaní náhradníci se snažili. Během zápasu jsem si vyslechnul kritiku na záměrně poskládaný silný tým pozdějších vítězů. Hru tak ovládly emoce a mírné potyčky :-).\r\n\r\n<strong>Bílí vs. žlutí 7:3 (5:0)</strong>\r\n\r\nPo zápase došlo na konzultace k jarnímu termínu roku 2010. Jelikož půjde o <strong>10.zápas</strong>, dojde na malou oslavu fotbalem. Těšte se na celodenní turnaj 4. mužstev, každý s každým, 2x20 min.. O všem budu včas informovat.\r\n\r\n<a href="http://www.haptip.cz/index.php?is=33&it=96">Zde</a> si prohlédněte fotogalerii.  \r\n\r\n<a href="images/fotbalek/sestava_zari2009.jpg" target="_blank"><obr>sestava_zari2009m.jpg</obr></a>\r\n</center>\r\n', '2009-10-03', '0000-00-00', 8, 30),
(8, 'Nový web', 'Po téměř půlročních přípravách byl spuštěn nový web. Jde o zbrusu nový kabát stránek www.haliska.borec.cz. Rád bych upozornil, že nový web ještě není hotov, nicméně je schopen provozu.', 'Nový web přináší nový design, který však dozná ještě drobných změn. Menu webu je tříděno stejně jako u webu starého. Pro přehlednost byl web doplněn o kalendář. Účastníky Haptipu potěší doplnění historických údajů z 1. fotbalové ligy a minulých ročníků Haptipu.    \r\nO všechny tyto novinky se postaral webmaster Martin Louda. \r\n\r\nU zrodu těchto stránek stáli kamarádi, kteří vlastními silami a znalostmi vytvořili dílo určené k mým 30. narozeninám, za což jim patří velký dík. Věřím, že i oni přijmou nový vzhled pozitivně.', '2008-02-24', '0000-00-00', 8, 1),
