INSERT INTO `texty` (`text_id`, `text_nazev`, `text_kr`, `text_dl`, `text_datumod`, `text_datumdo`, `text_autor`, `text_sekce`) VALUES
(80, 'Tenisový turnaj zaujal', 'První tenisový turnaj v sprnu 2008 zaznamenal velký úspěch u všech účastníků.', 'Na tenisových kurtech v Děhylově si zahráli všichni minimálně 3 zápasy. Většina soubojů ve dvou kvalifikačních skupinách nabídla dramatickou a vyrovnanou podívanou. Vrcholem sobotního odpoledne byly semifinálové duely, z nichž vzešli finalisté. \r\n \r\nVítězem se nakonec stal, po vítězství nad Petrem Hališkou, <strong>Pavel Sobol</strong>. \r\n\r\nPoděkování patří všem účastníkům turnaje: \r\n\r\nPavel Sobol \r\nŠárka Sobolová \r\nPetr Hališka \r\nLukáš Hrubý \r\nMartin Hellebrand \r\nMartin Richter \r\nJiří Bonczek \r\nLibor Szyrocki \r\n\r\n<center>\r\n<obr>tenis_1.jpg</obr>\r\n<obr>tenis_2.jpg</obr>\r\n</center>', '2009-06-04', '0000-00-00', 8, 60),
